import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.BXzK3EA4.js";const _=JSON.parse('{"title":"产品概述","description":"","frontmatter":{"title":"产品概述"},"headers":[],"relativePath":"app-center/guide/overview.md","filePath":"app-center/guide/overview.md","lastUpdated":1794381603000}'),o={name:"app-center/guide/overview.md"};function i(n,t,s,l,p,h){return r(),e("div",null,[...t[0]||(t[0]=[d('<h3 id="raksmart-应用中心是什么" tabindex="-1">RakSmart 应用中心是什么 <a class="header-anchor" href="#raksmart-应用中心是什么" aria-label="Permalink to &quot;RakSmart 应用中心是什么&quot;">​</a></h3><p>RakSmart 应用中心是一个一键部署开源应用的云服务平台。我们精选了社区中成熟、可靠的开源软件，将复杂的安装配置过程封装成简单的部署流程，让您无需具备专业的运维知识，也能快速拥有自己的应用服务。</p><p>目前应用中心提供以下几类应用：</p><table tabindex="0"><thead><tr><th>分类</th><th>应用</th><th>说明</th></tr></thead><tbody><tr><td>AI 智能体</td><td>OpenClaw、CoPaw</td><td>可接入多种大模型的 AI 智能体应用</td></tr><tr><td>数据库</td><td>MySQL、PostgreSQL</td><td>主流关系型数据库</td></tr><tr><td>内容管理</td><td>WordPress</td><td>全球最流行的建站系统</td></tr><tr><td>服务器管理</td><td>宝塔面板</td><td>可视化的服务器管理工具</td></tr></tbody></table><p>我们会持续关注社区中受欢迎的开源项目，不断丰富应用中心的选择。</p><h3 id="计费模式" tabindex="-1">计费模式 <a class="header-anchor" href="#计费模式" aria-label="Permalink to &quot;计费模式&quot;">​</a></h3><p>应用中心的应用本身不收取额外费用，您只需支付承载应用的云服务器费用，价格与购买普通云服务器完全相同。</p><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><p>如果您有以下需求，应用中心可以帮您节省大量时间：</p><ul><li><strong>快速验证想法</strong>：想试用某个开源应用，但不想花时间研究如何安装部署。</li><li><strong>付费 SaaS 备选方案</strong>：希望使用类似 SaaS 的服务，但更看重数据自主可控和长期成本。</li><li><strong>零基础建站</strong>：没有运维经验，但需要搭建自己的网站或服务。</li></ul><p>典型应用场景：</p><ul><li><strong>内容发布</strong>：使用 WordPress 搭建博客或企业官网时，您不需要了解域名解析、SSL 证书配置等技术细节，应用中心会自动完成这些配置，让您专注于内容创作。</li><li><strong>数据库服务</strong>：部署 MySQL 或 PostgreSQL 时，系统会自动完成安装配置，并附带可视化的管理面板（phpMyAdmin / pgAdmin），您可以通过网页界面管理数据库，无需记忆命令行操作。</li><li><strong>服务器管理</strong>：部署宝塔面板后，您可以通过网页界面管理服务器上的网站、数据库、文件等，无需掌握 Linux 命令行操作。</li></ul>',12)])])}const g=a(o,[["render",i]]);export{_ as __pageData,g as default};
